def finding(item, number, refs):
    fid, name, primary, required = item
    low = name.lower()
    kinds = [primary, KINDS[(number + 7) % len(KINDS)], KINDS[(number + 15) % len(KINDS)]]
    questions = [
      {"id": f"{fid}-q01", "text": f"Which stable identities, record class, source-qualified values and explicit unknowns establish {low}?", "kind": kinds[0], "answer_data": ["identifiers and class", "source-qualified values", "unknown and not-applicable states"]},
      {"id": f"{fid}-q02", "text": f"Who requested, authorized, performed, supplied, received, recorded or reported {low}, with which role, evidence and limits?", "kind": kinds[1], "answer_data": ["actors and roles", "authority and limits", "evidence and provenance"]},
      {"id": f"{fid}-q03", "text": f"Which event, authored, prepared, handover, occurrence, recorded, reported, ingested and knowledge times apply to {low}, and how is it validated or corrected?", "kind": kinds[2], "answer_data": ["distinct clinical and record times", "validation and discrepancy status", "successor correction and retention"]}
    ]
    return {"id": fid, "name": name, "description": f"Records {low} as source-qualified medication-lifecycle context while preserving the distinctions among request, dispense, administration, statement, product knowledge and clinical consequence.", "source_refs": refs, "questions": questions,
            "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed data for {low} with child-event identity, source, authority, status, event time, record time, evidence and provenance.", "value_kind": "collection", "cardinality": "1" if required else "0..n", "required": required, "source_refs": refs}],
            "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or successor-versioned medication evidence for {low}.", "media_or_form": ["logical medication assertion", "request, dispense, administration, statement, safety, reconciliation or projection record"], "serial": True, "identity_strategy": f"Aggregate ID plus independent request, dispense, administration, statement or assertion ID for {fid}; patient, medication, date, encounter and claim never identify an event alone.", "source_refs": refs}], "inline_only_rationale": None}

def structure():
    bundles = []
    number = 0
    for bid, bname, rationale, layers in ROWS:
        rendered_layers = []
        for lid, lname, refs, items in layers:
            rendered_findings = []
            for item in items:
                number += 1
                rendered_findings.append(finding(item, number, refs))
            rendered_layers.append({"id": lid, "name": lname, "description": f"Groups source-qualified medication context for {lname.lower()}.", "source_refs": refs, "findings": rendered_findings})
        bundles.append({"id": bid, "name": bname, "description": f"Groups governed medication context for {bname.lower()}.", "rationale": rationale + ".", "source_refs": sorted({ref for layer in layers for ref in layer[2]}), "layers": rendered_layers})
    return {"bundles": bundles}

